public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> remainingNums = Arrays.asList(nums).subList(0, i).stream().mapToInt(n -> n).boxed().collect(Collectors.toList());
        List<List<Integer>> permutations = permute(remainingNums.toArray());
        for (List<Integer> permutation : permutations) {
            permutation.add(0, num);
            result.add(permutation);
        }
    }
    return result;
}

