public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to store the nodes to visit
    Queue<Integer> queue = new LinkedList<>();

    // Mark node 0 as visited and add it to the queue
    graph.visited[0] = true;
    queue.add(0);

    // Initialize the time to 0
    int time = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int node = queue.remove();

        // If the current node has an apple, return the current time
        if (hasApple[node]) {
            return time;
        }

        // Get the neighbors of the current node
        int[] neighbors = graph.neighbors[node];

        // Loop through the neighbors
        for (int neighbor : neighbors) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!graph.visited[neighbor]) {
                graph.visited[neighbor] = true;
                queue.add(neighbor);
            }
        }

        // Increment the time
        time++;
    }

    // If no node has an apple, return -1
    return -1;
}

